import at.pinzker.taskloop.*;import java.util.*;
public class EnglishInputTests {
 static int count;static void check(boolean b){count++;if(!b)throw new AssertionError("English test "+count);}
 public static void main(String[] a){TimeZone.setDefault(TimeZone.getTimeZone("Europe/Vienna"));long now=java.time.LocalDateTime.parse("2026-10-07T08:00:00").atZone(java.time.ZoneId.of("Europe/Vienna")).toInstant().toEpochMilli();TextParser.Result r=TextParser.parse("Tomorrow at 9 am check invoice daily",now,true);check(r.kind==1);check(r.title.equals("Check invoice"));Calendar c=Calendar.getInstance();c.setTimeInMillis(r.when);check(c.get(Calendar.DAY_OF_MONTH)==8&&c.get(Calendar.HOUR_OF_DAY)==9);r=TextParser.parse("Today at 3:30 pm call supplier",now,true);c.setTimeInMillis(r.when);check(c.get(Calendar.HOUR_OF_DAY)==15&&c.get(Calendar.MINUTE)==30);r=TextParser.parse("In 30 minutes send email",now,true);check(r.when==now+1800000);check(r.title.equals("Send email"));r=TextParser.parse("Every 2 weeks at 10:00 review offers",now,true);check(r.kind==2&&r.step==2);r=TextParser.parse("Weekdays at 9 am review inbox",now,true);check(r.kind==4&&r.mask==31);r=TextParser.parse("Daily at 9 am check invoice; remind again after 20 minutes",now,true);check(r.pause==20&&r.kind==1);r=TextParser.parse("In 2 days call supplier",now,true);check(r.when==now+172800000);r=TextParser.parse("Today at 12 am check alarm",now,true);c.setTimeInMillis(r.when);check(c.get(Calendar.HOUR_OF_DAY)==0);r=TextParser.parse("Today at 12 pm check alarm",now,true);c.setTimeInMillis(r.when);check(c.get(Calendar.HOUR_OF_DAY)==12);r=TextParser.parse("Call mum and dad",now,true);check(r.title.equals("Call mum and dad"));System.out.println("PASS: "+count+" English input checks");}
}
